result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/prodline/audit.py", "content": """"Hash-chained audit log.

Every pipeline stage appends a JSON record. Each record carries the hash of
its predecessor; a record's own hash is SHA-256 over the canonical JSON of
the record with the ``hash`` field removed. Verification walks the chain and
recomputes every hash.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

GENESIS_PREV = "0" * 64


def _canonical(obj: Any) -> str:
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def compute_record_hash(record: dict) -> str:
    payload = {k: v for k, v in record.items() if k != "hash"}
    return hashlib.sha256(_canonical(payload).encode("utf-8")).hexdigest()


class AuditLog:
    """Append-only JSONL audit log with per-record hash chaining."""

    def __init__(self, path: str | Path):
        self.path = Path(path)
        self.records: list[dict] = []
        if self.path.exists():
            self.records = self._read_records(self.path)

    @staticmethod
    def _read_records(path: Path) -> list[dict]:
        records = []
        for line in path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line:
                records.append(json.loads(line))
        return records

    def append(self, stage: str, detail: dict | None = None) -> dict:
        prev_hash = self.records[-1]["hash"] if self.records else GENESIS_PREV
        record = {
            "seq": len(self.records),
            "ts": _now(),
            "stage": stage,
            "detail": detail or {},
            "prev_hash": prev_hash,
        }
        record["hash"] = compute_record_hash(record)
        self.records.append(record)
        self._flush()
        return record

    def _flush(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open("a", encoding="utf-8") as fh:
            fh.write(_canonical(self.records[-1]) + "\n")

    def last_hash(self) -> str:
        return self.records[-1]["hash"] if self.records else GENESIS_PREV


def _now() -> str:
    import datetime

    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="milliseconds")


def verify_chain(path: str | Path) -> tuple[bool, str]:
    """Verify the hash chain of an audit log file.

    Returns (ok, reason). ok is True only when every record's stored hash
    matches its recomputed hash and every prev_hash links to its predecessor.
    """
    p = Path(path)
    if not p.exists():
        return False, "audit log missing"
    try:
        records = AuditLog._read_records(p)
    except json.JSONDecodeError as exc:
        return False, f"malformed JSON: {exc}"
    prev = GENESIS_PREV
    for i, rec in enumerate(records):
        if rec.get("seq") != i:
            return False, f"record {i}: sequence number out of order"
        if rec.get("prev_hash") != prev:
            return False, f"record {i}: prev_hash does not link to predecessor"
        if compute_record_hash(rec) != rec.get("hash"):
            return False, f"record {i}: hash mismatch"
        prev = rec["hash"]
    return True, f"{len(records)} records verified"
